// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // 1. Call the public entry point
        c.sudicideAnyone();
        // 2. General rule: after the call, the contract's own address (address(c)) has no code (selfdestruct removes it)
        uint256 size;
        assembly {
            size := extcodesize(c)
        }
        assertTrue(size == 0, "Contract should have no code after selfdestruct");
    }
}

