pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable caller) public {
        vm.assume(caller != address(0));
        uint256 initialBalance = 1 ether;
        vm.deal(address(c), initialBalance);
        vm.deal(caller, 0);
        uint256 callerBalanceBefore = caller.balance;
        vm.prank(caller);
        c.sudicideAnyone();
        uint256 callerBalanceAfter = caller.balance;
        assertTrue(callerBalanceAfter == callerBalanceBefore + initialBalance);
    }
}

